#include "ksPartEnableTask.h"
#include <stdexcept>
#include <iostream>
int main(){using T=ks::PartEnableTask;using S=T::Stage;using R=T::Read;using W=T::Write;unsigned cases=0;for(unsigned part=0;part<256;++part)for(unsigned generation=0;generation<256;++generation){T t;unsigned writes=0,used=0;auto clock=[](W){return 3u;};while(t.stage()!=S::Complete){if(t.awaiting()){if(!t.resumeChild(uint8_t(part+7)))throw std::runtime_error("Resume failed");continue;}auto cost=t.nextClocks(clock);if(t.advanceBefore(cost-1,[](R){return 0;},[](W,uint8_t){},clock))throw std::runtime_error("Early step");used+=t.advanceBefore(cost,[&](R r){return r==R::Input?part:generation;},[&](W w,uint8_t value){if(w==W::Part?(writes!=0||value!=part):w==W::Enable?(writes!=1||value!=1):(writes!=2||value!=uint8_t(generation+8)))throw std::runtime_error("Wrong write/order");++writes;},clock);}if(writes!=3||t.part()!=uint8_t(part+7)||used!=100)throw std::runtime_error("Wrong lifecycle/clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure part enable properties\n";}
